/** Minimal glob -> regexp. Supports `*`, `**` and `?`, which is all `srcExclude` uses. */
function globToRegExp(glob: string): RegExp {
  let out = ''
  for (let i = 0; i < glob.length; i += 1) {
    const char = glob[i]
    if (char === '*') {
